style.css:
/* Pinterest Custom Sage + Batang Theme */

/* Import Batang-style fallback fonts */
* {
    font-family: Batang, "BatangChe", "Nanum Myeongjo", serif !important;
    color: #556b5d !important; /* dark sage green text */
}

/* Main page background (lets wallpaper show through) */
body {
    background: transparent !important;
    backdrop-filter: blur(4px);
}

/* Make panels semi-transparent so background is visible */
div,
header,
section,
nav,
main {
    background: rgba(245,248,242,0.45) !important;
    backdrop-filter: blur(8px) !important;
    border: 1px solid rgba(85,107,93,0.2) !important;
}

/* Pins/cards */
[data-test-id="pin"],
article {
    background: rgba(255,255,255,0.30) !important;
    border-radius: 18px !important;
}

/* Search bar */
input {
    background: rgba(255,255,255,0.35) !important;
    color: #556b5d !important;
    border: 1px solid #556b5d !important;
}

/* Buttons */
button {
    background: rgba(85,107,93,0.15) !important;
    color: #556b5d !important;
    border-radius: 14px !important;
    border: 1px solid #556b5d !important;
}

/* Links/titles */
a, h1, h2, h3 {
    color: #4d6657 !important;
}

/* Remove harsh white Pinterest blocks */
[style*="background-color: rgb(255, 255, 255)"] {
    background: transparent !important;
}/* Font + text color */
*{
font-family: Batang, "Nanum Myeongjo", serif !important;
color:#556b5d !important;
}

/* Page background */
body{
background: transparent !important;
}

/* Only style interface panels, not pins/images */
header,
nav,
[data-test-id="desktop-header"],
[data-test-id="search-box-container"]{
background: rgba(245,248,242,.55)!important;
backdrop-filter: blur(8px)!important;
}

/* Keep pins visible */
img{
opacity:1 !important;
visibility:visible !important;
display:block !important;
filter:none !important;
}

/* Pin cards */
[data-test-id="pin"]{
background: rgba(255,255,255,.15)!important;
border-radius:16px!important;
}
